const fs = require('fs');
const { PDFParse } = require('pdf-parse');

const pdfPath = '/workspace/testbed/docs/handbook.pdf';
const buf = fs.readFileSync(pdfPath);

(async () => {
  try {
    const parser = new PDFParse({ data: buf });
    await parser.load();

    // Get info
    const info = await parser.getInfo();
    console.log('=== PDF INFO ===');
    console.log(JSON.stringify(info, null, 2));

    // Get full text
    const text = await parser.getText();
    console.log('\n=== EXTRACTED TEXT ===');
    console.log(text);

    // Get first page screenshot for OCR
    try {
      const screenshot = await parser.getScreenshot(1, { scale: 2 });
      if (screenshot) {
        fs.writeFileSync('/workspace/page1.png', screenshot);
        console.log('\n=== First page image saved to /workspace/page1.png ===');
      }
    } catch (e) {
      console.log('Screenshot error:', e.message);
      // Try getImage instead
      try {
        const img = await parser.getImage(1);
        if (img) {
          fs.writeFileSync('/workspace/page1.png', img);
          console.log('\n=== First page image saved via getImage ===');
        }
      } catch (e2) {
        console.log('getImage error:', e2.message);
      }
    }

    parser.destroy();
  } catch (err) {
    console.error('Error:', err.message);
    console.error(err.stack);
  }
})();

