    // Try different arg patterns for getScreenshot
    for (const args of [
      [{ page: 1, scale: 2 }],
      [{ pageNumber: 1 }],
      [{}],
      [],
    ]) {
      try {
        const result = await parser.getScreenshot(...args);
        console.log('getScreenshot succeeded with args:', JSON.stringify(args));
        console.log('Result type:', typeof result, result?.constructor?.name);
        if (Buffer.isBuffer(result) || result instanceof Uint8Array) {
          fs.writeFileSync('/workspace/page1.png', result);
