        } else {
          console.log('Result:', JSON.stringify(result)?.slice(0, 300));
        }
        break;
      } catch (e) {
        console.log(`getScreenshot(${JSON.stringify(args)}) failed:`, e.message);
      }
    }

    parser.destroy();
  } catch (err) {
    console.error('Error:', err.message);
  }
})();

const fs = require('fs');
const { PDFParse } = require('pdf-parse');

const pdfPath = '/workspace/testbed/docs/handbook.pdf';
const buf = fs.readFileSync(pdfPath);

(async () => {
  try {
    const parser = new PDFParse({ data: buf });
    await parser.load();

    // Get screenshot
    const result = await parser.getScreenshot({ page: 1, scale: 2 });

    if (result && result.pages && result.pages[0]) {
      const pageData = result.pages[0];
      // pageData.data is a Buffer-like object with PNG data
      const pngBuffer = Buffer.from(Object.values(pageData.data));
      fs.writeFileSync('/workspace/page1.png', pngBuffer);
      console.log('=== First page rendered and saved to /workspace/page1.png ===');
      console.log(`Image size: ${pngBuffer.length} bytes`);
    }

    parser.destroy();

    // Now OCR the image using Tesseract.js
    console.log('\n=== Running OCR on first page image ===');
    const { createWorker } = require('tesseract.js');
    const worker = await createWorker('eng');
    const { data: { text } } = await worker.recognize('/workspace/page1.png');
    console.log('\n=== OCR TEXT ===');
    console.log(text);
    await worker.terminate();

  } catch (err) {
    console.error('Error:', err.message);
    console.error(err.stack);
  }
})();

const fs = require('fs');
const { createCanvas } = require('canvas');

(async () => {
  // Dynamic import for pdfjs-dist (ESM)
  const pdfjsLib = await import('pdfjs-dist/legacy/build/pdf.mjs');

  const pdfPath = '/workspace/testbed/docs/handbook.pdf';
  const data = new Uint8Array(fs.readFileSync(pdfPath));

  const doc = await pdfjsLib.getDocument({ data }).promise;
  console.log(`=== PDF loaded: ${doc.numPages} page(s) ===\n`);

  // --- Extract text from all pages ---
  console.log('=== EXTRACTED TEXT (all pages) ===');
  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc.getPage(i);
    const textContent = await page.getTextContent();
    const pageText = textContent.items.map(item => item.str).join(' ');
    console.log(`\n--- Page ${i} ---`);
    console.log(pageText);
  }

  // --- Render first page to image ---
  console.log('\n\n=== RENDERING PAGE 1 TO IMAGE ===');
  const page = await doc.getPage(1);
  const scale = 2.0;
  const viewport = page.getViewport({ scale });

  const canvas = createCanvas(viewport.width, viewport.height);
  const context = canvas.getContext('2d');

  // White background
  context.fillStyle = 'white';
  context.fillRect(0, 0, viewport.width, viewport.height);

  await page.render({
    canvasContext: context,
    viewport: viewport,
  }).promise;

  const pngBuffer = canvas.toBuffer('image/png');
  fs.writeFileSync('/workspace/page1_rendered.png', pngBuffer);
  console.log(`Page 1 rendered: ${pngBuffer.length} bytes -> /workspace/page1_rendered.png`);

  // --- OCR the rendered image ---
  console.log('\n=== RUNNING OCR ON PAGE 1 IMAGE ===');
  const { createWorker } = require('tesseract.js');
  const worker = await createWorker('eng');
  const { data: ocrData } = await worker.recognize('/workspace/page1_rendered.png');
  console.log('\n=== OCR RESULT ===');
  console.log(ocrData.text);
  console.log(`OCR confidence: ${ocrData.confidence}%`);
  await worker.terminate();
})();

