const ExcelJS = require('exceljs');

(async () => {
  const workbook = new ExcelJS.Workbook();
  workbook.creator = 'PDF Extractor';
  workbook.created = new Date();

  const sheet = workbook.addWorksheet('Extracted Text');

  // Style the header row
  sheet.columns = [
    { header: 'Line', key: 'line', width: 8 },
    { header: 'Content', key: 'content', width: 80 },
  ];

  // Bold header row
  sheet.getRow(1).font = { bold: true, size: 12 };
  sheet.getRow(1).fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FF4472C4' },
  };
  sheet.getRow(1).font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };

  // The extracted text from handbook.pdf
  const extractedText = [
    'Employee Handbook',
    'Welcome to the company. This handbook outlines our policies.',
  ];

  extractedText.forEach((text, i) => {
    sheet.addRow({ line: i + 1, content: text });
  });

  // Auto-fit row heights and light styling for data rows
  sheet.eachRow((row, rowNumber) => {
    if (rowNumber > 1) {
      row.font = { size: 11 };
      row.alignment = { vertical: 'middle', wrapText: true };
    }
  });

  // Add a metadata sheet
  const metaSheet = workbook.addWorksheet('Metadata');
  metaSheet.columns = [
    { header: 'Property', key: 'property', width: 20 },
    { header: 'Value', key: 'value', width: 50 },
  ];
  metaSheet.getRow(1).font = { bold: true, size: 12 };
  metaSheet.getRow(1).fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FF4472C4' },
  };
  metaSheet.getRow(1).font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };

  metaSheet.addRow({ property: 'Source File', value: 'handbook.pdf' });
  metaSheet.addRow({ property: 'Total Pages', value: 1 });
  metaSheet.addRow({ property: 'Extraction Method', value: 'pdfjs-dist + Tesseract.js OCR' });
  metaSheet.addRow({ property: 'OCR Confidence', value: '95%' });
  metaSheet.addRow({ property: 'Extracted On', value: new Date().toISOString() });

  const outputPath = '/workspace/handbook_extracted.xlsx';
  await workbook.xlsx.writeFile(outputPath);
  console.log(`Excel file created: ${outputPath}`);
})();

